import re

from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone

__author__ = 'Marcin Usielski, Michal Ernst'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'marcin.usielski@nokia.com, michal.ernst@nokia.com'


class Boot(GenericUnixCommand):
    """Boot command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, expected_prompt=r"toor4nsn@fzm-lsp-k2:.*#",
                 login='toor4nsn', password='oZPS0POrRieRtu', runner=None):
        """
        Boot command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: Prompt of the starting shell
        :param expected_prompt: Prompt of the target shell reached after entering Argon
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command

        """
        super(Boot, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.expected_prompt = CommandTextualGeneric._calculate_prompt(expected_prompt)
        self.login = login
        self.password = password
        self._login_sent = False
        self._password_sent = False
        self.timeout = 150

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "boot"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._parse_login(line)
            self._parse_password(line)
            self._parse_expected_prompt(line)
        except ParsingDone:
            pass

    _re_login = re.compile(r"login:", re.IGNORECASE)

    def _parse_login(self, line):
        if self._regex_helper.search_compiled(Boot._re_login, line):
            if not self._login_sent:
                self._login_sent = True
                self._password_sent = False
                self.connection.sendline(self.login)
            raise ParsingDone()

    _re_password = re.compile(r"Password:", re.IGNORECASE)

    def _parse_password(self, line):
        if self._regex_helper.search_compiled(Boot._re_password, line):
            if not self._password_sent:
                self._password_sent = True
                self._login_sent = False
                self.connection.sendline(self.password)
            raise ParsingDone()

    def _parse_expected_prompt(self, line):
        """
        Set result if parse prompt in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search_compiled(self.expected_prompt, line):
            self.set_result({})
        raise ParsingDone()


COMMAND_OUTPUT = """
ARGON # boot
toor4nsn@fzm-lsp-k2: #"""

COMMAND_KWARGS = {}

COMMAND_RESULT = {}

